const FAILED_RETRY_MS = 7 * 24 * 60 * 60 * 1000;
const BODY_LIMIT_BYTES = 200_000;
const DEFAULT_LIMIT = 25;

type FetchFn = (url: string | URL | Request, init?: RequestInit) => Promise<Response>;

export interface LinkEnrichmentEntry {
